-- ============================================================

-- 1. AGREGAR COLUMNAS A PROVEEDORES
-- ============================================================

ALTER TABLE "PROVEEDORES" ADD COLUMN IF NOT EXISTS mundo VARCHAR(20) DEFAULT 'COM';
ALTER TABLE "PROVEEDORES" ADD COLUMN IF NOT EXISTS has_exchange BOOLEAN DEFAULT TRUE;
ALTER TABLE "PROVEEDORES" ADD COLUMN IF NOT EXISTS withdrawal_days INTEGER DEFAULT 30;
ALTER TABLE "PROVEEDORES" ADD COLUMN IF NOT EXISTS exchange_policy TEXT DEFAULT 'Política estándar';
ALTER TABLE "PROVEEDORES" ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT NOW();
ALTER TABLE "PROVEEDORES" ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

UPDATE "PROVEEDORES" SET has_exchange = TRUE WHERE has_exchange IS NULL OR has_exchange = false;
UPDATE "PROVEEDORES" SET withdrawal_days = 30 WHERE withdrawal_days IS NULL OR withdrawal_days = 0;

-- ============================================================
-- 2. CREAR TABLA PRODUCTOS_CATALOGO
-- ============================================================

CREATE TABLE IF NOT EXISTS "PRODUCTOS_CATALOGO" (
    id SERIAL PRIMARY KEY,
    barcode VARCHAR(50) UNIQUE NOT NULL,
    name TEXT NOT NULL,
    mundo VARCHAR(20) DEFAULT 'COM',
    marca VARCHAR(10),
    supplier_rut VARCHAR(20),
    supplier_name TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_pc_barcode ON "PRODUCTOS_CATALOGO"(barcode);
CREATE INDEX IF NOT EXISTS idx_pc_supplier ON "PRODUCTOS_CATALOGO"(supplier_rut);

-- ============================================================
-- 3. CREAR TABLA PRODUCTO_PROVEEDOR
-- ============================================================

CREATE TABLE IF NOT EXISTS "PRODUCTO_PROVEEDOR" (
    id SERIAL PRIMARY KEY,
    product_barcode VARCHAR(50) NOT NULL,
    provider_rut VARCHAR(20) NOT NULL,
    mundo VARCHAR(20) DEFAULT 'COM',
    marca VARCHAR(10),
    is_primary BOOLEAN DEFAULT FALSE,
    has_exchange BOOLEAN,
    withdrawal_days INTEGER,
    exchange_policy TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(product_barcode, provider_rut)
);
CREATE INDEX IF NOT EXISTS idx_pp_barcode ON "PRODUCTO_PROVEEDOR"(product_barcode);
CREATE INDEX IF NOT EXISTS idx_pp_provider ON "PRODUCTO_PROVEEDOR"(provider_rut);

-- ============================================================
-- 4. CREAR VISTA VIEW_POLITICAS_EFECTIVAS
-- ============================================================

CREATE OR REPLACE VIEW "VIEW_POLITICAS_EFECTIVAS" AS
SELECT 
    pp.id,
    pp.product_barcode,
    pc.name AS product_name,
    pp.provider_rut,
    pr.name AS provider_name,
    pp.mundo,
    pp.marca,
    pp.is_primary,
    COALESCE(pp.has_exchange, pr.has_exchange) AS effective_has_exchange,
    COALESCE(pp.withdrawal_days, pr.withdrawal_days, 30) AS effective_withdrawal_days,
    COALESCE(pp.exchange_policy, pr.exchange_policy) AS effective_exchange_policy
FROM "PRODUCTO_PROVEEDOR" pp
LEFT JOIN "PRODUCTOS_CATALOGO" pc ON pp.product_barcode = pc.barcode
JOIN "PROVEEDORES" pr ON pp.provider_rut = pr.rut;

-- ============================================================
-- 5. CREAR TRIGGERS
-- ============================================================

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER update_proveedores_upd
    BEFORE UPDATE ON "PROVEEDORES" FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

CREATE OR REPLACE TRIGGER update_pc_upd
    BEFORE UPDATE ON "PRODUCTOS_CATALOGO" FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

CREATE OR REPLACE TRIGGER update_pp_upd
    BEFORE UPDATE ON "PRODUCTO_PROVEEDOR" FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

