-- ============================================================
-- 9. VERIFICACIÓN
-- ============================================================

SELECT 'PROVEEDORES' as tabla, COUNT(*) as total FROM "PROVEEDORES"
UNION ALL SELECT 'PRODUCTOS_CATALOGO', COUNT(*) FROM "PRODUCTOS_CATALOGO"
UNION ALL SELECT 'PRODUCTO_PROVEEDOR', COUNT(*) FROM "PRODUCTO_PROVEEDOR";

SELECT rut, name, has_exchange, withdrawal_days FROM "PROVEEDORES" LIMIT 5;

SELECT product_barcode, provider_name, effective_withdrawal_days, effective_has_exchange
FROM "VIEW_POLITICAS_EFECTIVAS" LIMIT 5;
